import{R as e,e as o,f as r,U as n}from"./chunks/framework.ywem4qy5.js";const u=JSON.parse('{"title":"Cloudflare Turnstile","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/captchas/cloudflare-turnstile.md","filePath":"integrations/captchas/cloudflare-turnstile.md","lastUpdated":1775908585000}'),a={name:"integrations/captchas/cloudflare-turnstile.md"};function i(s,t,l,g,h,d){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="cloudflare-turnstile" tabindex="-1">Cloudflare Turnstile <a class="header-anchor" href="#cloudflare-turnstile" aria-label="Permalink to &quot;Cloudflare Turnstile&quot;">​</a></h1><p>Follow the below steps to connect Formie to Cloudflare Turnstile.</p><h3 id="step-1-open-the-captcha-settings" tabindex="-1">Step 1. Open the Captcha Settings <a class="header-anchor" href="#step-1-open-the-captcha-settings" aria-label="Permalink to &quot;Step 1. Open the Captcha Settings&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Captchas</strong>.</li><li>Select <strong>Cloudflare Turnstile</strong> in the left-hand sidebar.</li><li>Turn on <strong>Enabled</strong>.</li></ol><h3 id="step-2-create-a-turnstile-widget" tabindex="-1">Step 2. Create a Turnstile Widget <a class="header-anchor" href="#step-2-create-a-turnstile-widget" aria-label="Permalink to &quot;Step 2. Create a Turnstile Widget&quot;">​</a></h3><ol><li>Go to the <a href="https://dash.cloudflare.com/?to=/:account/turnstile" target="_blank" rel="noreferrer">Cloudflare Turnstile dashboard</a> and sign in to your account.</li><li>Open the <strong>Turnstile</strong> page.</li><li>Click <strong>Add widget</strong>.</li><li>Enter a <strong>Widget name</strong>.</li><li>Add the hostname or hostnames where the form will run.</li><li>Choose the <strong>Widget mode</strong> you want to use in Cloudflare: <strong>Managed</strong>, <strong>Non-interactive</strong>, or <strong>Invisible</strong>.</li><li>Click <strong>Create</strong>.</li><li>Copy the <strong>Site key</strong> and <strong>Secret key</strong>.</li></ol><h3 id="step-3-connect-formie-to-turnstile" tabindex="-1">Step 3. Connect Formie to Turnstile <a class="header-anchor" href="#step-3-connect-formie-to-turnstile" aria-label="Permalink to &quot;Step 3. Connect Formie to Turnstile&quot;">​</a></h3><ol><li>Paste the <strong>Site Key</strong> into the <strong>Site Key</strong> field in Formie.</li><li>Paste the <strong>Secret Key</strong> into the <strong>Secret Key</strong> field in Formie.</li><li>Choose the front-end options you want in Formie, such as <strong>Theme</strong>, <strong>Size</strong>, <strong>Appearance</strong>, and <strong>Execution</strong>.</li><li>Save the captcha settings.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to protect.</li><li>Enable <strong>Cloudflare Turnstile</strong> for that form.</li><li>For multi-page forms, turn on <strong>Show on All Pages</strong> if the captcha should run on every page instead of only the final submit step.</li><li>Save the form.</li></ol><p>Turnstile widget mode is chosen in Cloudflare for the site key you created. Formie does not change that mode, so make sure you pick the right widget in Cloudflare first.</p>',11)])])}const p=e(a,[["render",i]]);export{u as __pageData,p as default};
